  const systemStatusText = useMemo<string>(() => 
    isSystemReady ? 'STABILIZED' : 'INITIALIZING',
    [isSystemReady]
  );

  return (
    <div className="min-h-screen bg-zinc-950 text-white font-mono p-4">
      <header className="border-b border-zinc-800 pb-4 mb-8">
